css:
table, th, td {
  border: 1px solid black;
  border-collapse: collapse;
}

.info {
    display: flex;
    display: -webkit-box;
    justify-content: justify;
    -webkit-box-pack: justify;
    border-bottom: 1px solid #dddddd;
    padding-bottom: 2px;

}

.header {
    display: flex;
    display: -webkit-box;
    justify-content: justify;
    -webkit-box-pack: justify;
    border-bottom: 1px solid #dddddd;
    padding-bottom: 4px;
}

html:
{% set company = frappe.db.get_value("Company", doc.company, ["*"], as_dict = true) %}
{% set letter_head = frappe.db.get_value("Letter Head", company.default_letter_head, ["image"], as_dict=true) %}
{% set links = frappe.get_all('Dynamic Link', filters={'link_doctype': 'Company', 'link_name': doc.company, 'parenttype': 'Address'}, fields=['parent']) %}
{%set room_charges = "{:,}".format(doc.daily_room_charges|int) %}
{% if links %}
{% set address = frappe.db.get_value("Address", links[0].parent, ["*"], as_dict=true) %}
{% endif %}
{%set initial_encounter = json.loads(doc.initial_encounter_json)%}
{%set chief_complaint = initial_encounter.chief_complaint%}
{%set allergies = initial_encounter.allergies%}
{%set investigation = initial_encounter.investigation_done%}
{%set clinical_examination = initial_encounter.clinical_examination%}
{%set diagnosis = initial_encounter.diagnosis%}
{%set plan = initial_encounter.plan%}
{%set follow_up = initial_encounter.follow_up%}
{%set history_of_present_illness = initial_encounter.history_of_present_illness%}
{%set past_medical_history = initial_encounter.past_medical_history%}
{%set vital_signs = initial_encounter.vital_signs%}
{% set dob = frappe.utils.getdate(doc.dob) %} {# Replace with actual DOB #}
{% set today = frappe.utils.nowdate() %}
{% set birth_date = frappe.utils.getdate(dob) %}
{% set current_date = frappe.utils.getdate(today) %}
{% set age = current_date.year - birth_date.year - ((current_date.month, current_date.day) < (birth_date.month, birth_date.day)) %}

{% macro header() %}
<div class="header">
    <div>
        <img src="{{ letter_head.image }}" style="width:100px; margin-bottom:32px;" />
    </div>
    <div style="text-align: center">
        <h3>Premium Care<br>Clinic</h3>
        <H5><u>Initial Encounter Report</u></H5>
    </div>
    <div style="text-align: right;">
        {% if address.address_title %}<p style="font-weight: bold; font-size: large;">{{ address.address_title }}</p>{% endif %}
        {% if address.address_line1 %}<p>{{ address.address_line1 }}</p>{% endif %}
        {% if address.city %}<p>{{ address.city }}</p>{% endif %}
        {% if address.pincode %}<p>{{ address.pincode }}</p>{% endif %}
        <p>Tel: 4908128</p>
        <p>BRN: C22188669</p>
    </div>
</div>
{% endmacro %}

{% macro info() %}
<div class="info">
    <div class="col-6">
        <section class="patient-info">

            <p><strong>Name:</strong> {{ doc.patient_name }}</p>
            <p><strong>Patient HIS:</strong> {{ doc.patient }}</p>

            <p>
            {% if doc.dob %}
                <strong>D.O.B:</strong> {{ frappe.utils.formatdate(doc.dob) }}  ({{age}} yrs) 
            {% endif %}
            ({{ "M" if  doc.gender == "Male" else "F"  }})
            </p>
            {% if doc.address %}
            <p><strong>Address:</strong> </p>
            <p style="white-space-collapse: preserve; max-width:200px">{{ doc.address }}</p>
            {% endif %}
            <p><strong>Tel:</strong> {{ doc.mobile }}</p>
            {%if doc.uid %}
                <p><strong>NID:</strong> {{ doc.uid }}</p>
            {% endif %}
        </section>
    </div>
    <div class="col-">
        <section class="patient-info">
            {% if doc.primary_practitioner %}
                <p><strong>Attending Practitioner (1):</strong> {{ doc.primary_practitioner }}</p>
            {% endif %}
            {%if doc.secondary_practitioner%}
                <p><strong>Attending Practitioner (2):</strong> {{ doc.secondary_practitioner }}</p>
            {%endif%}    
            <p><b>Date of Admission: </b> {{ doc.admitted_datetime}}</p>
            <p><b> Encounter Date: </b> {{frappe.utils.nowdate()}} </p>
        </section>
    </div>
</div>
{% endmacro %}


<div>
    {{ header() }}
    {{ info() }}

    {%if chief_complaint|length > 0 %}
    <div id="ChiefComplaint">
        <h4>Chief Complaint </h4>
        <p>{{ chief_complaint|replace("\n","<br>")}}</p>
    </div>
    {%endif%}

    {%if history_of_present_illness|length > 0 %}
    <div id="history_of_present_illness">
        <h4>History of Present Illness</h4>
        <p>{{ history_of_present_illness|replace("\n","<br>")}}</p>
    </div>
    {%endif%}

    {%if past_medical_history|length > 0 %}
    <div id="past_medical_history">
        <h4>Past Medical History</h4>
        <p>{{ past_medical_history|replace("\n","<br>")}}</p>
    </div>
    {%endif%}

    {%if allergies|length > 0 %}
    <div id="allergies">
        <h4>Allergies</h4>
        <p>{{ allergies|replace("\n","<br>")}}</p>
    </div>
    {%endif%}

    {%if vital_signs|length > 0 %}
    <div id="vital_signs">
        <h4>Vital Signs</h4>
        <p>{{ vital_signs|replace("\n","<br>")}}</p>
    </div>
    {%endif%}

    {%if clinical_examination|length > 0 %}
    <div id="ClinicalExamination">
        <h4>Clinical Examination</h4>
        <p>{{ clinical_examination|replace("\n","<br>")}}</p>
    </div>
    {%endif%}

    {%if investigation|length > 0 %}
    <div id="investigation">
        <h4>Investigation</h4>
        <p>{{ investigation|replace("\n","<br>")}}</p>
    </div>
    {%endif%}

    {%if diagnosis|length > 0 %}
    <div id="diagnosis">
        <h4>Initial Diagnosis</h4>
        <p>{{ diagnosis|replace("\n","<br>")}}</p>
    </div>
    {%endif%}

    {%if plan|length > 0 %}
    <div id="plan">
        <h4>Treatment Plan</h4>
        <p>{{ plan|replace("\n","<br>")}}</p>
    </div>
    {%endif%}

    {%if follow_up|length > 0 %}
    <div id="follow_up">
        <h4>Follow Up</h4>
        <p>{{ follow_up|replace("\n","<br>") }}</p>
    </div>
    {%endif%}
</div>
